const apiUrl = process.env.WORDPRESS_API_URL?.trim();
const username = process.env.WORDPRESS_USERNAME?.trim();
const appPassword = process.env.WORDPRESS_APP_PASSWORD?.trim();
if (!apiUrl || !username || !appPassword) throw new Error("WordPress configuration is missing.");
const base = apiUrl.replace(/\/?$/, "/");
const authorization = `Basic ${Buffer.from(`${username}:${appPassword}`).toString("base64")}`;
const dryRun = !process.argv.includes("--publish");
const results = [];

for (const post of posts) {
  const beforeResponse = await fetch(`${base}posts/${post.id}?context=edit&_fields=id,slug,status,title,content`, {
    headers: { Authorization: authorization },
  });
  const before = await beforeResponse.json();
  if (!beforeResponse.ok) throw new Error(`Failed to fetch post ${post.id}: ${beforeResponse.status}`);
  if (before.slug !== post.slug || before.status !== "publish") {
    throw new Error(`Post ${post.id} identity or status mismatch.`);
  }
  if (dryRun) {
    results.push({ id: post.id, title: post.title, status: "checked", beforeLength: before.content?.raw?.length ?? 0, afterLength: post.content.length });
    continue;
  }
  const updateResponse = await fetch(`${base}posts/${post.id}?context=edit`, {
    method: "POST",
    headers: { Authorization: authorization, "Content-Type": "application/json" },
    body: JSON.stringify({ title: post.title, excerpt: post.excerpt, content: post.content, status: "publish" }),
  });
  const updated = await updateResponse.json();
  if (!updateResponse.ok) throw new Error(`Failed to update post ${post.id}: ${updateResponse.status} ${updated.code ?? ""}`);
  const verifyResponse = await fetch(`${base}posts/${post.id}?context=edit&_fields=id,slug,status,title,content,modified,link`, {
    headers: { Authorization: authorization },
  });
  const verified = await verifyResponse.json();
  if (!verifyResponse.ok || verified.content?.raw !== post.content || verified.status !== "publish") {
    throw new Error(`Verification failed for post ${post.id}.`);
  }
  results.push({ id: post.id, title: post.title, status: verified.status, modified: verified.modified, link: verified.link, contentLength: post.content.length });
}

console.log(JSON.stringify({ dryRun, results }, null, 2));
